// The analog voltage switch's program: it names the standard analog classes' voltage members, so the SDK's scan
// finds them and sets the switch per board. It prints the switch, opens the converter's first input where the board
// has one, reads one count, and reads the voltage: computed under the switch, refused without it. The lines the gate
// reads in order: the board and the switch, the count, the voltage or the refusal, the end. The facts came in before
// Main, generated by the SDK from the row's facts file.
using System;
using System.Device.Analog;
using System.Globalization;
using Lamella.Hardware;

namespace Rhu.Hosted;

internal static class Program
{
    private static int Main()
    {
        var board = new TargetBoard();
        Console.WriteLine("TBVOLTS: " + board.Name + "; the switch " + (AnalogVoltage.IsSupported ? "true" : "false"));
        try
        {
            using AnalogController adc = board.CreateAnalogController(0);
            int pin = -1;
            for (int i = 0; i < adc.PinCount && pin < 0; i++)
            {
                if (adc.SupportsAnalogInput(i))
                {
                    pin = i;
                }
            }

            if (pin < 0)
            {
                Console.WriteLine("TBVOLTS: no pin carries an analog input");
            }
            else
            {
                using AnalogInputPin input = adc.OpenPin(pin);
                Console.WriteLine("TBVOLTS: pin " + pin + " reads " + input.ReadRaw() + " of " + input.AdcResolutionBits + " bits");
                if (AnalogVoltage.IsSupported)
                {
                    var volts = input.ReadVoltage();
                    var full = input.MaxVoltage;
                    Console.WriteLine("TBVOLTS: the voltage " + volts.Volts.ToString("F4", CultureInfo.InvariantCulture) + " V of " + full.Volts.ToString("F4", CultureInfo.InvariantCulture) + " V");
                }
                else
                {
                    try
                    {
                        _ = input.ReadVoltage();
                        Console.WriteLine("TBVOLTS: ReadVoltage answered with the switch false");
                    }
                    catch (NotSupportedException e)
                    {
                        Console.WriteLine("TBVOLTS: NotSupportedException: " + e.Message);
                    }
                }
            }
        }
        catch (NotSupportedException e)
        {
            Console.WriteLine("TBVOLTS: NotSupportedException: " + e.Message);
        }

        Console.WriteLine("TBVOLTS: end");
        return 0;
    }
}
